import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';import '../../chat/support_chat_screen.dart';class ChatAdminPage extends StatelessWidget{const ChatAdminPage({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Customer Service')),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('support_threads').orderBy('lastMessageAt',descending:true).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());if(s.data!.docs.isEmpty)return const Center(child:Text('Belum ada pesan bantuan'));return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(leading:Badge(isLabelVisible:x['unreadForAdmin']==true,label:const Text('!'),child:const CircleAvatar(child:Icon(Icons.support_agent))),title:Text(x['userId']??'Pengguna'),subtitle:Text(x['lastMessage']??''),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>SupportChatScreen(admin:true,threadId:d.id))));}).toList());}));}